import{_ as o,o as t,c as a,a0 as r}from"./chunks/framework.Bmhw_dvp.js";const m=JSON.parse('{"title":"dira에 대하여","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://dira.proofer.tech/docs/what-is-dira"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"dira"}],["meta",{"property":"og:locale","content":"ko_KR"}],["meta",{"property":"og:url","content":"https://dira.proofer.tech/docs/what-is-dira"}],["meta",{"property":"og:title","content":"dira에 대하여"}],["meta",{"property":"og:description","content":"티켓을 큐에 넣으면 cron에 물린 워커가 claude 세션에 넘깁니다. 파일시스템이 곧 큐인 티켓 디스패처."}],["meta",{"property":"og:image","content":"https://dira.proofer.tech/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"name":"twitter:card","content":"summary_large_image"}]]},"headers":[],"relativePath":"docs/what-is-dira.md","filePath":"docs/what-is-dira.md"}'),c={name:"docs/what-is-dira.md"};function d(i,e,n,p,s,l){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="dira에-대하여" tabindex="-1">dira에 대하여 <a class="header-anchor" href="#dira에-대하여" aria-label="Permalink to &quot;dira에 대하여&quot;">​</a></h1><p><strong>내 PC에서 쉽게 돌리는 멀티 에이전트 매니지먼트 시스템입니다.</strong> 넣으신 요구를 pm이 티켓으로 쪼개고, 페르소나별 워커가 그 티켓을 하나씩 물어 세션을 띄우고, 결과를 통합 브랜치에 올립니다. 사람은 하고 싶은 걸 말하고, 물어보면 답변해주는 일만 하면 됩니다.</p><p>dira는 서버가 없습니다. 티켓을 포함한 모든 동작에 파일시스템을 사용하며 필요에 따라 내부 파일들을 직접 확인하고 수정해도 문제없이 동작합니다.</p><p>이름은 <code>dir</code> + <code>jira</code>입니다. 디렉터리의 <code>dir</code>이고, 그 디렉터리에 기반하여 <code>jira</code>와 같이 티켓 매니징을 할 수 있다는 오마주입니다.</p><h2 id="용어-넷" tabindex="-1">용어 넷 <a class="header-anchor" href="#용어-넷" aria-label="Permalink to &quot;용어 넷&quot;">​</a></h2><p>나머지 장은 이 넷을 안다는 전제로 썼습니다. 화면에도 그대로 나오는 말입니다.</p><p><strong>티켓</strong>은 마크다운 파일 하나입니다. 무엇을 원하는지(<code>## Goal</code>)와 무엇이 되면 끝인지 (<code>## Done when</code>)를 적습니다.</p><p><strong>큐</strong>는 그 티켓 파일들이 담긴 디렉터리 하나입니다(<code>&lt;프로젝트&gt;/.dira</code>). 하위 디렉터리로 나누지 않고 파일명 접미사(<code>.wip</code>·<code>.done</code>)로 상태를 구분합니다. 그래야 이름을 바꾸는 한 번이 곧 잠금이 됩니다.</p><p><strong>워커</strong>는 30초마다 깨어나 큐를 훑고 열려 있는 티켓 하나를 무는 셸 스크립트입니다. 한 번 실행에 티켓 한 건입니다. 동시에 여러 개를 돌리고 싶으시면 설정값을 올리는 것이 아니라 워커를 하나 더 만듭니다.</p><p><strong>세션</strong>은 워커가 그 티켓을 들고 띄운 에이전트 프로세스입니다(기본은 <code>claude -p</code>). 페르소나 프로필과 협업 프로토콜, 티켓 본문을 프롬프트로 조립해 넘기고, 세션이 끝날 때까지 워커는 기다립니다.</p><h2 id="앱과-엔진" tabindex="-1">앱과 엔진 <a class="header-anchor" href="#앱과-엔진" aria-label="Permalink to &quot;앱과 엔진&quot;">​</a></h2><p>앱이 제품입니다. 프로젝트를 만들고, 요구를 접수하고, 티켓이 도는 것을 보고, 도는 세션에 말을 걸고, 워커를 늘리는 일이 전부 화면에서 끝납니다. 큐 파일을 직접 열 일은 없습니다.</p><p>엔진은 앱이 없어도 도는 그 아래층입니다. <code>tick.sh</code>와 <code>tickets.py</code> 두 파일이고, bash와 python3 표준 라이브러리 밖으로 나가지 않습니다. 앱은 자기가 판정한 것을 큐에 쓰지 않고 엔진에 위임합니다. 화면과 cron이 같은 답을 내게 하는 방법이 그것 하나뿐이기 때문입니다. cron은 정해진 주기마다 명령을 대신 실행해 주는, 맥에 이미 들어 있는 기능입니다. 화면 없이 cron만으로 굴리는 것도 되는데, 그건 <a href="/docs/cron">엔진만으로 돌리기</a>에서 다룹니다.</p><h2 id="안-하는-것" tabindex="-1">안 하는 것 <a class="header-anchor" href="#안-하는-것" aria-label="Permalink to &quot;안 하는 것&quot;">​</a></h2><ul><li>서버로 배포하지 않습니다. 호스팅도 원격 접속도 없습니다. 큐는 쓰시는 맥의 파일시스템 위에만 있습니다.</li><li>인증과 멀티유저가 없습니다. 파일시스템 권한이 곧 권한입니다.</li><li>데스크톱 앱은 macOS(Apple Silicon)에서만 돕니다. 엔진 자체는 macOS와 Linux에서 돕니다.</li><li>우선순위가 없습니다. 큐를 도는 순서를 정하는 것은 만든 날짜와 <code>deps</code>뿐입니다. <code>deps</code>는 이 티켓보다 먼저 끝나야 하는 티켓을 가리키는 칸입니다.</li></ul><p>다음은 <a href="/docs/install">설치</a>입니다.</p>',16)])])}const g=o(c,[["render",d]]);export{m as __pageData,g as default};
